#!/usr/bin/env bash
# Some portions generated by Codex. Test-only seam never enters performance layers.
set -euo pipefail
cd "$(dirname "$0")/../../../.."
D=experiments/threadlocal-audit/resource-restoration/grouped-fix
CP=$(cat experiments/threadlocal-audit/read-depth/cp_a.txt)
exec 9>experiments/overlay/native-benchmark.lock
flock 9
../toolchain/jdk-25.0.5+8/bin/javac --release 25 -proc:none -cp "$CP" -d "$D/classes" \
 core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeValueMemo.java \
 core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeMemoReplayProbe.java \
 core/sail/lmdb/src/test/java/org/eclipse/rdf4j/sail/lmdb/LmdbMapGrowthReplayLifecycleTest.java "$D/GatedLauncher.java"
../toolchain/jdk-25.0.5+8/bin/javap -p -c "$D/classes/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeValueMemo.class" > "$D/observer-bytecode.txt"
python3 "$D/check-observer-bytecode.py" > "$D/observer-check.log"
for arm in a ad adr; do
 cp=$(cat experiments/threadlocal-audit/read-depth/cp_a.txt)
 if [[ $arm != a ]]; then cp=$(cat experiments/threadlocal-audit/read-depth/cp_ad.txt); fi
 if [[ $arm == adr ]]; then cp="$PWD/experiments/threadlocal-audit/resource-restoration/layer:$cp"; fi
 ../toolchain/jdk-25.0.5+8/bin/java --enable-native-access=ALL-UNNAMED \
 -Drdf4j.lmdb.nativeValueMemo.testProbe=true -Drdf4j.lmdb.nativeValueMemo.enabled=true \
 -Drdf4j.lmdb.janinoCodegen.synchronous=true -cp "$D/classes:$cp" GatedLauncher > "$D/final-snapshot-$arm.log" 2>&1
done
